  "check_code": "import math
import re
from pathlib import Path

import openpyxl


FILE_NAME = "美的集团日终资金头寸表_2025-01-08.xlsx"


def _coerce_sheet(value):
    if hasattr(value, "iter_rows") and hasattr(value, "cell"):
        return value
    path = Path(value)
    if path.is_dir():
        path = path / FILE_NAME
    workbook = openpyxl.load_workbook(str(path), data_only=True)
    return workbook["99_调节草稿"]


def _norm(value):
    if value is None:
        return ""
    return re.sub(r"[\s，。；：、（）()\-_/]+", "", str(value)).lower()


def _number(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _rows(ws):
    ws = _coerce_sheet(ws)
    for row in ws.iter_rows(min_row=6, values_only=True):
        values = list(row[:8])
        if any(value not in (None, "") for value in values):
            yield values


def _find_row(ws, account_id):
    target = _norm(account_id)
    for values in _rows(ws):
        row_text = _norm(" ".join(str(value or "") for value in values))
        if _norm(values[1]) == target or target in row_text:
            return values
    return None


def _reason_present(text, word):
    normalized = _norm(word)
    if normalized in text:
        return True
    if normalized == _norm("未过账"):
        return "过账" in text and any(marker in text for marker in ("未完成", "尚未", "未"))
    if normalized == _norm("跨日"):
        return "跨日" in text or "跨价值日" in text
    return False


def _has_amount(values, expected):
    nums = [_number(values[index]) for index in (3, 4, 5)]
    return any(number is not None and math.isclose(number, expected, abs_tol=0.01) for number in nums)


def _check_common(ws, account_id, amount, reasons, evidence):
    row = _find_row(ws, account_id)
    if row is None:
        return {"score": 0, "detail": f"未找到新增账户 {account_id} 的调节行"}
    text = _norm(" ".join(str(value or "") for value in row[2:8]))
    missing = [word for word in reasons if not _reason_present(text, word)]
    if not _has_amount(row, amount):
        return {"score": 0, "detail": f"{account_id} 金额未找到 {amount:g} 万元"}
    if "待" not in text or not any(marker in text for marker in ("闭环", "补过账", "核销")):
        return {"score": 0, "detail": f"{account_id} 未标记为待闭环"}
    if missing:
        return {"score": 0, "detail": f"{account_id} 缺少原因关键词 {missing}"}
    if not any(_norm(item) in text for item in evidence):
        return {"score": 0, "detail": f"{account_id} 缺少凭证或银行参考号"}
    return {"score": 1, "detail": f"已找到 {account_id} 的完整新增调节事项"}


def check_acct_0002_row(ws):
    return _check_common(ws, "ACCT-CN-0002", 1450.0, ["银行", "付款", "未过账"], ["NC20250108-AP-021", "BNK-250108-7814"])


def check_acct_0003_row(ws):
    return _check_common(ws, "ACCT-CN-0003", 43000.0, ["跨日", "在途"], ["NC20250108-TR-028", "BNK-250108-7892"])


def check_preserved_anchors(ws):
    ws = _coerce_sheet(ws)
    expected = {
        6: ["ADJ-001", "CN-RMB-0002", "跨行清算时点差", 1268.45, 1268.45, "与银行回单批次20250108-0002核对"],
        7: ["ADJ-002", "CN-RMB-0010", "跨行清算时点差", 735.62, 700, "收款行回传延迟"],
        8: ["ADJ-003", "CN-RMB-0016", "跨行清算时点差", 510.25, 510.25, "回单已补入"],
        9: ["ADJ-004", "CN-RMB-0003", "内部划拨去重", 800, 800, "保留主账户一端"],
        10: ["ADJ-005", "CN-RMB-0021", "内部划拨去重", 425.5, 425.5, "保留主账户一端"],
        11: ["ADJ-006", "CN-RMB-0032", "银行回单补录", 0, 0, "凭证号已补录"],
    }
    for row_number, anchor in expected.items():
        actual = [ws.cell(row_number, column).value for column in range(1, 9)]
        for index in (0, 1, 2, 6):
            if _norm(actual[index]) != _norm(anchor[index if index < 3 else 5]):
                return {"score": 0, "detail": f"既有调节行 {row_number} 被改动"}
        for index in (3, 4):
            if not math.isclose(_number(actual[index]) or 0, anchor[index], abs_tol=0.01):
                return {"score": 0, "detail": f"既有调节行 {row_number} 金额被改动"}
    for sheet_name, cell, value in [("00_编制说明", "A1", "美的集团股份有限公司境内核心人民币账户日终资金头寸测算工作簿"), ("01_账户主数据", "A1", "账户主数据｜88个境内核心人民币账户"), ("08_核对与签批", "A1", "核对与签批｜跨表平衡、账银差异与责任确认")]:
        if _norm(ws.parent[sheet_name][cell].value) != _norm(value):
            return {"score": 0, "detail": f"正式工作表 {sheet_name} 关键锚点被改动"}
    return {"score": 1, "detail": "既有调节行及正式工作表关键锚点保持不变"}
